import { describe, expect, it } from 'vitest';

import { numberedOutputName, outputNameForScene } from '../src/lib/video-output';

describe('视频导出文件名', () => {
  it('使用起始场景名并按导出内容选择扩展名', () => {
    expect(outputNameForScene('chapter.txt', 'video-audio')).toBe('chapter.mp4');
    expect(outputNameForScene('chapter.txt', 'audio')).toBe('chapter.wav');
  });

  it('在扩展名前追加重名编号', () => {
    expect(numberedOutputName('chapter.mp4', 1)).toBe('chapter (1).mp4');
    expect(numberedOutputName('chapter', 2)).toBe('chapter (2)');
  });
});
